WITH lines AS (SELECT id, customer_id, created_at, tag FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) e AS tag), base AS (SELECT *, TRIM(tag) AS clean_tag FROM lines WHERE created_at > DATE '2025-03-02' AND customer_id IS NOT NULL), joined AS (SELECT src.*, b.segment FROM base src LEFT JOIN customers b ON src.customer_id = b.id), cleaned AS (SELECT *, CASE WHEN segment = 'Consumer' THEN 1 ELSE 0 END AS is_consumer, COALESCE(segment, 'N/A') AS segment_clean FROM joined WHERE tag IS NOT NULL) SELECT id, customer_id, created_at, tag, segment, is_consumer, segment_clean FROM cleaned;
